import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788358256000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>One section per tool: what it does, its parameters, and — for the one guarded tool — what a person is asked.</p><p>All of them are registered unless you say otherwise. <code>HEALTHCHECKS_ALLOW_TOOLS</code> and <code>HEALTHCHECKS_DENY_TOOLS</code> narrow the list to the ones you want, and <code>essential</code> selects the ones marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. Every tool that reports anything from the instance carries <code>untrusted: true</code> and <code>source: &quot;healthchecks&quot;</code> as fields of that object — <code>get_api_key_info</code> is without it, and <code>get_status</code> carries it only when the instance answered something other than <code>OK</code>.</p><p>Three markers recur:</p><ul><li>👤 <strong>asks a person</strong> — through MCP elicitation, a dialog the model cannot answer on its behalf. Where the client cannot show one, the tool falls back to a two-call <code>confirm_token</code>. See <a href="/guide/approval">Asking a person</a>.</li><li>🔑 <strong>needs a read-write key</strong> — the tool only reads, but Healthchecks gates the endpoint behind a read-write key anyway, and refuses a read-only one with <code>401 &quot;wrong api key&quot;</code>. The tool says what that really means.</li><li>🆔 <strong>needs a UUID</strong> — a <code>unique_key</code> will not do, because the API routes that path on a UUID-shaped segment and answers anything else with a bare 404.</li></ul><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><p>Registered always, including under <code>HEALTHCHECKS_READ_ONLY</code>.</p><h3 id="list-checks" tabindex="-1"><code>list_checks</code> <a class="header-anchor" href="#list-checks" aria-label="Permalink to “list_checks”">​</a></h3><p><strong>essential</strong></p><p>Lists the checks of the project the API key belongs to, as compact summaries — identifier, name, slug, tags, status, last and next ping, and either <code>timeout</code> or <code>schedule</code>. Descriptions are omitted; <code>get_check</code> has them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>tag</code></td><td>string[]</td><td>Only checks carrying <strong>all</strong> of these. A tag cannot contain a space</td></tr><tr><td><code>slug</code></td><td>string</td><td>Slugs are not unique, so this can match several</td></tr><tr><td><code>status</code></td><td><code>new</code> <code>up</code> <code>grace</code> <code>down</code> <code>paused</code></td><td>Filtered client-side — the API offers no status filter</td></tr><tr><td><code>limit</code></td><td>number, 1…500</td><td>Default 50</td></tr></tbody></table><p>The endpoint has no pagination whatsoever: it returns every check in the project in one response. <code>limit</code> and the result budget are this server&#39;s, and the result says how many checks the project actually holds.</p><h3 id="get-check" tabindex="-1"><code>get_check</code> <a class="header-anchor" href="#get-check" aria-label="Permalink to “get_check”">​</a></h3><p><strong>essential</strong></p><p>One check with every field, including <code>desc</code> and the keyword filters. <code>channels</code> is split into a list, the legacy derived <code>subject</code> / <code>subject_fail</code> are dropped, and <code>schedule_kind</code> says whether the check is driven by <code>timeout</code> or by <code>schedule</code> — the API has no <code>kind</code> field, only the presence of one or the other.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>A UUID <strong>or</strong> a 40-character <code>unique_key</code>. Not a slug</td></tr></tbody></table><p>Returned as untrusted content: <code>desc</code> is free text.</p><h3 id="list-pings-🔑-🆔" tabindex="-1"><code>list_pings</code> 🔑 🆔 <a class="header-anchor" href="#list-pings-🔑-🆔" aria-label="Permalink to “list_pings 🔑 🆔”">​</a></h3><p><strong>essential</strong></p><p>Recent pings of a check, newest first, each with type, timestamp, ping number, source address, method and — where one was recorded — duration and <code>body_url</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID</td></tr><tr><td><code>type</code></td><td><code>success</code> <code>start</code> <code>fail</code> <code>log</code> <code>ign</code></td><td>Filtered client-side</td></tr><tr><td><code>limit</code></td><td>number, 1…500</td><td>Default 50</td></tr></tbody></table><p>The instance caps this at 100 pings on a free plan and 1000 on a paid one, and there is no pagination, so older pings cannot be reached at all.</p><h3 id="get-ping-body-🔑-🆔" tabindex="-1"><code>get_ping_body</code> 🔑 🆔 <a class="header-anchor" href="#get-ping-body-🔑-🆔" aria-label="Permalink to “get_ping_body 🔑 🆔”">​</a></h3><p>The body a job POSTed with one ping — usually its output, and the fastest way to see why a check failed. Returned as untrusted content, truncated at 64 KB.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID</td></tr><tr><td><code>n</code></td><td>number</td><td>Ping number, as <code>list_pings</code> reports it</td></tr></tbody></table><p>A 404 here means any of four things — no such check, no such ping, the ping carried no body, or the ping is older than the instance keeps — and the tool says all four rather than passing the number on. A 503 is the object storage being briefly unavailable and is worth retrying.</p><h3 id="list-flips" tabindex="-1"><code>list_flips</code> <a class="header-anchor" href="#list-flips" aria-label="Permalink to “list_flips”">​</a></h3><p><strong>essential</strong></p><p>The up/down transitions of a check: the history behind its current status.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID or <code>unique_key</code></td></tr><tr><td><code>seconds</code></td><td>number</td><td>Only flips from the last N seconds</td></tr><tr><td><code>start</code></td><td>number</td><td>Unix timestamp — only flips newer than this</td></tr><tr><td><code>end</code></td><td>number</td><td>Unix timestamp — only flips older than this</td></tr><tr><td><code>limit</code></td><td>number</td><td>Default 50</td></tr></tbody></table><p>The instance keeps the current month and the two before it. A window that runs backwards is refused here rather than at the API.</p><h3 id="list-integrations-🔑" tabindex="-1"><code>list_integrations</code> 🔑 <a class="header-anchor" href="#list-integrations-🔑" aria-label="Permalink to “list_integrations 🔑”">​</a></h3><p>The project&#39;s notification integrations, with the UUIDs that <code>create_check</code> and <code>update_check</code> accept in <code>channels</code>. Integrations themselves can only be created in the web UI; the Management API has no endpoint for it.</p><p>No parameters.</p><h3 id="list-badges" tabindex="-1"><code>list_badges</code> <a class="header-anchor" href="#list-badges" aria-label="Permalink to “list_badges”">​</a></h3><p>The project&#39;s status badge URLs, one entry per tag plus <code>*</code> for the project as a whole. The plain variants treat a check in its grace period as up; the ones suffixed <code>3</code> report up, late and down separately.</p><p>No parameters.</p><h3 id="get-status" tabindex="-1"><code>get_status</code> <a class="header-anchor" href="#get-status" aria-label="Permalink to “get_status”">​</a></h3><p>Whether the configured instance is reachable and its database is answering. This endpoint needs <strong>no API key</strong>, which makes it the first thing to try when something is not working — it separates &quot;wrong key&quot; from &quot;wrong URL&quot;.</p><p>No parameters.</p><h3 id="get-api-key-info" tabindex="-1"><code>get_api_key_info</code> <a class="header-anchor" href="#get-api-key-info" aria-label="Permalink to “get_api_key_info”">​</a></h3><p>Which instance is configured, whether the key is accepted, and whether it is read-only or read-write — which in turn decides whether checks are identified by <code>uuid</code> or by <code>unique_key</code> and which tools are reachable at all. Runs two harmless GETs to find out rather than guessing from the <code>hcr_</code> prefix, which only the hosted service uses.</p><p>No parameters.</p><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><p>Registered unless <code>HEALTHCHECKS_READ_ONLY=true</code>. All of them need a read-write API key and a UUID.</p><h3 id="create-check" tabindex="-1"><code>create_check</code> <a class="header-anchor" href="#create-check" aria-label="Permalink to “create_check”">​</a></h3><p><strong>essential</strong></p><p>Creates a check.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>name</code>, <code>slug</code>, <code>desc</code></td><td>string</td><td><code>slug</code> needs an instance with API v3</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>Stored space-delimited, so no tag may contain a space</td></tr><tr><td><code>timeout</code></td><td>number</td><td>Seconds, 60…31536000</td></tr><tr><td><code>schedule</code>, <code>tz</code></td><td>string</td><td>Cron or systemd OnCalendar, plus an IANA zone</td></tr><tr><td><code>grace</code></td><td>number</td><td>Seconds, 60…31536000</td></tr><tr><td><code>channels</code></td><td><code>*</code> or string[]</td><td>Integration UUIDs or exact names. <strong>Default <code>*</code></strong></td></tr><tr><td><code>manual_resume</code></td><td>boolean</td><td>A paused check then ignores pings until <code>resume_check</code></td></tr><tr><td><code>methods</code></td><td><code>&quot;&quot;</code> or <code>POST</code></td><td><code>&quot;&quot;</code> accepts HEAD, GET and POST</td></tr><tr><td><code>start_kw</code>, <code>success_kw</code>, <code>failure_kw</code></td><td>string[]</td><td>Stored comma-delimited, so no keyword may contain a comma</td></tr><tr><td><code>filter_subject</code>, <code>filter_body</code>, <code>filter_http_body</code>, <code>filter_default_fail</code></td><td>boolean</td><td>Where the keywords apply</td></tr><tr><td><code>unique</code></td><td>string[]</td><td><code>name</code> <code>slug</code> <code>tags</code> <code>timeout</code> <code>grace</code> — turns this into an upsert</td></tr></tbody></table><p>Three things the API does that this tool does not simply forward:</p><ul><li><strong><code>timeout</code> and <code>schedule</code> cannot be combined.</strong> Upstream, <code>schedule</code> wins and <code>timeout</code> is discarded without a word. Passing both is an error here.</li><li><strong><code>channels</code> defaults to <code>*</code>.</strong> The API&#39;s own default is <em>no</em> integrations, which produces a check that looks healthy, reports correctly and never tells anyone when it stops. The result says which default was applied.</li><li><strong>An empty <code>channels</code> list is refused.</strong> It serialises to the empty string, which the API reads as &quot;no integrations&quot; — the same silent loss of alerting that <code>pause_check</code> is gated for. Clearing every integration is done in the web UI, in front of someone who can see what it means.</li><li><strong><code>unique</code> turns a create into an update.</strong> When it matches, the API returns 200 and the modified existing check instead of 201. The result says so.</li></ul><h3 id="update-check-🆔" tabindex="-1"><code>update_check</code> 🆔 <a class="header-anchor" href="#update-check-🆔" aria-label="Permalink to “update_check 🆔”">​</a></h3><p><strong>essential</strong></p><p>Changes the given fields of a check; anything not passed stays as it was. Takes the same parameters as <code>create_check</code> (minus <code>unique</code>) plus <code>check</code>.</p><p>Two exceptions to &quot;not passed stays as it was&quot;: <code>channels</code> <strong>replaces</strong> the integration list rather than adding to it, and setting <code>schedule</code> on a check that used <code>timeout</code> switches it over. An update with no fields at all is refused rather than sent.</p><h3 id="pause-check-🆔" tabindex="-1"><code>pause_check</code> 🆔 <a class="header-anchor" href="#pause-check-🆔" aria-label="Permalink to “pause_check 🆔”">​</a></h3><p>Pauses a check: it stops expecting pings, and stops alerting.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID</td></tr></tbody></table><p><strong>Not gated</strong>, and it used to be. <code>resume_check</code> puts it back and nothing is lost in between; a dialog in front of a reversible state change is how people learn to tick without reading, and that attention is what <code>delete_check</code> needs. What pausing costs is stated in the description instead: while paused, a job that stops running goes unnoticed.</p><h3 id="resume-check-🆔" tabindex="-1"><code>resume_check</code> 🆔 <a class="header-anchor" href="#resume-check-🆔" aria-label="Permalink to “resume_check 🆔”">​</a></h3><p><strong>essential</strong></p><p>Puts a paused check back into the <code>new</code> state, waiting for its next ping. Not gated: it restores alerting rather than removing it. Answers 409 if the check was not paused.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID</td></tr></tbody></table><h3 id="delete-check-👤-🆔" tabindex="-1"><code>delete_check</code> 👤 🆔 <a class="header-anchor" href="#delete-check-👤-🆔" aria-label="Permalink to “delete_check 👤 🆔”">​</a></h3><p>Deletes a check permanently.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>check</code></td><td>string</td><td>UUID</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>From the first call of this tool</td></tr></tbody></table><p><strong>Asks a person first</strong>, and marked destructive to the client. The UUID cannot be recovered and no new check can take it, so everything still pinging that URL breaks. The confirmation text says so and points at <code>pause_check</code> as the reversible alternative. <code>confirm_token</code> is only used on the fallback path, where the client cannot show a dialog. The API returns the deleted object, and this tool keeps it in the result — the last record of what the check was.</p>`,68)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};